        ByteSize(budget.reserve_bytes as u64),
        ByteSize(budget.budget_bytes as u64),
        prefill_only.map_or_else(String::new, |prefill| format!(
            ", prefill-only chunk {} (scratch reservation {})",
            prefill.chunk_size,
            ByteSize(
