    let mirrored = moe_topo.uses_tensor_replicated_moe();
    let local_ranks = if mirrored { 1 } else { loaded.workers.len() };
    let (load_txs, load_rxs): (Vec<_>, Vec<_>) = (0..local_ranks)
        .map(|_| {
